function renderResources(e,data,total,msg){e.replaceChildren();const remaining=document.createElement('div');remaining.className='number-pill';const rows=[];function repaint(){const used=data.reduce((a,b)=>a+b[1],0);remaining.textContent=`Fichas dispoñibles: ${total-used} / ${total}`;rows.forEach((r,i)=>r.textContent=String(data[i][1]));}e.append(remaining);data.forEach((arr,i)=>{let row=document.createElement('div');row.className='resource-row';let name=document.createElement('span');name.className='resource-name';name.textContent=`${arr[0]} (mín. ${arr[2]})`;let minus=makeBtn('−',()=>{data[i][1]=Math.max(0,data[i][1]-1);repaint()},'counter');let plus=makeBtn('+',()=>{let used=data.reduce((a,b)=>a+b[1],0);if(used<total)data[i][1]++;repaint()},'counter');let value=document.createElement('span');value.className='resource-amt';rows.push(value);row.append(name,minus,value,plus);e.append(row)});repaint();e.append(makeBtn('✓ Verificar reparto',()=>{if(data.every(r=>r[1]>=r[2]))complete(msg);else feedback('Falta garantir algunha das necesidades mínimas. Revisa as cifras.',true)},'primary'))}
function taskMarket(){const e=getC();const choices=[['Pagar unha tarifa xusta por fabricar sensores, sen excluír a ninguén do monte.',true],['Vender en exclusiva o caudal vital ao mellor postor.',false],['Privatizar para sempre os datos meteorolóxicos financiados en común.',false]];for(const [label,yes] of choices)e.append(makeBtn(label,()=>yes?complete('Contrato posible: actividade económica con límites sobre o común.'):feedback('A oferta crea un monopolio sobre un recurso compartido. Examina outra.',true),'cardbtn'))}
