function taskForest(){const e=getC();let places=[['Ladeira exposta',true],['Regato e ribeira',true],['Interior do bosque',true],['Aula pechada',false]];let box=document.createElement('div');box.className='task-grid';places.forEach(([label,yes],i)=>{let b=makeBtn('🌳 '+label,()=>{if(task.seen.has(i))return;if(!yes)return feedback('A aula serve para estudar, pero non detecta por si soa o que acontece no monte.',true);task.seen.add(i);b.classList.add('active');feedback(`Sensores de campo instalados: ${task.seen.size}/3.`);if(task.seen.size===3)complete('Os sensores axudan; as persoas coñecedoras do monte interpretan os datos.')});box.append(b)});e.append(box)}
