function taskBudget(){const e=getC();e.innerHTML='<p class="note">Axusta o reparto dun orzamento de 100 unidades. A suma non pode superar 100 e cada dereito ten un mínimo.</p>';const d=[['Protección do monte',30,30],['Coidados e servizos',25,25],['Innovación e enerxía',25,25]];const rows=[],wrap=document.createElement('div');wrap.className='sliders';d.forEach((row,i)=>{let div=document.createElement('div');div.className='sliderow';let lbl=document.createElement('label');lbl.textContent=row[0];let input=document.createElement('input');input.type='range';input.min=0;input.max=100;input.step=5;input.value=row[1];let out=document.createElement('output');out.textContent=row[1]+' u.';input.oninput=()=>{row[1]=+input.value;out.textContent=row[1]+' u.';update()};div.append(lbl,input,out);wrap.append(div)});const sum=document.createElement('div');sum.className='number-pill';function update(){let t=d.reduce((n,row)=>n+row[1],0);sum.textContent=`Comprometidas: ${t}/100 · Reserva: ${100-t}`;sum.style.color=t>100?'#ff8b9a':''}update();e.append(wrap,sum,makeBtn('✓ Aprobar un orzamento viable',()=>{let t=d.reduce((n,row)=>n+row[1],0);t<=100&&d.every(row=>row[1]>=row[2])?complete('O orzamento deixa marxe para imprevistos e atende ás tres prioridades.'):feedback(t>100?'Non se poden comprometer máis de 100 unidades.':'Unha prioridade quedou por baixo do mínimo.',true)},'primary'))}
function taskSequence(){const e=getC(),labels=['BOMBO','CAIXA','CHASCA'];const grid=document.createElement('div');grid.className='beat-grid';labels.forEach((lbl,r)=>{let name=document.createElement('span');name.className='beat-label';name.textContent=lbl;grid.append(name);for(let c=0;c<8;c++){let b=makeBtn('',()=>{task.sequence[r][c]=!task.sequence[r][c];b.classList.toggle('active',!!task.sequence[r][c]);soundCue(r);});b.className='step';b.setAttribute('aria-label',`${lbl}, pulso ${c+1}`);grid.append(b)}});e.append(grid);const note=document.createElement('p');note.className='note';note.textContent='Crea unha base de oito pulsos. Toca os cadrados para acender ou apagar golpes de tres instrumentos.';e.append(note);const actions=document.createElement('div');actions.className='task-actions';actions.append(makeBtn('♫ Reproducir patrón',()=>{for(let c=0;c<8;c++){const ix=c;setTimeout(()=>task.sequence.forEach((row,r)=>{if(row[ix])soundCue(r)}),c*230)}feedback('Escoita o teu patrón: non emprega cancións de terceiros.')}),makeBtn('✓ Gardar secuencia',()=>{const hits=task.sequence.flat().filter(Boolean).length,rows=task.sequence.filter(r=>r.some(Boolean)).length;hits>=5&&rows>=2?complete('Compuxeches unha secuencia orixinal para o val.'):feedback('Activa cinco golpes distribuídos en polo menos dous instrumentos.',true)},'primary'));e.append(actions)}
function taskSignal(){const e=getC();const goal=state.scene===31?73:61;let current=15;const row=document.createElement('div');row.className='sliderow';row.innerHTML='<label>Frecuencia libre</label>';const input=document.createElement('input');input.type='range';input.min=0;input.max=100;input.value=15;const out=document.createElement('output');out.textContent='015';input.addEventListener('input',()=>{current=+input.value;out.textContent=String(current).padStart(3,'0');feedback(`Sinal detectado: ${Math.abs(current-goal)} puntos de desviación.`)});row.append(input,out);e.append(row,document.createElement('p'));e.lastChild.textContent=`O teu receptor detectou a canle ${goal}. Axusta o dial cunha tolerancia de ±5.`;e.lastChild.className='note';e.append(makeBtn('📡 Conectar frecuencia',()=>Math.abs(current-goal)<=5?complete('Sintonizaches unha canle libre de control central.'):feedback('Hai demasiado ruído. Aproxima o dial ao sinal.',true),'primary'))}
function taskDialogue(){const e=getC();const q=[['Por que hai copias en papel?','Porque o que se desconecta non debería desaparecer da memoria.'],['Quen escribiu RC/0?','Persoas do proxecto. A confianza non pode substituír as probas.'],['Que podemos facer agora?','Que todo o mundo coñeza os feitos e poida decidir.']];q.forEach(([question,answer],i)=>{let b=makeBtn('Preguntar: '+question,()=>{if(task.seen.has(i))return;task.seen.add(i);b.classList.add('active');let p=document.createElement('p');p.className='hint';p.textContent='Lúa: «'+answer+'»';e.append(p);if(task.seen.size===3)complete('Escoitaches as respostas antes de xulgar a Lúa.');});e.append(b)})}
