function drawLoop(ms){motion=requestAnimationFrame(drawLoop);if($('game').classList.contains('hidden')||document.hidden||ms-lastFrame<35)return;lastFrame=ms;const rect=canvas.getBoundingClientRect();if(rect.width<10)return;let dpr=Math.min(window.devicePixelRatio||1,2),w=Math.round(rect.width*dpr),h=Math.round(rect.height*dpr);if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h}const ctx=drawCtx;ctx.setTransform(w/820,0,0,h/400,0,0);makeScene(ctx,ms);if(task.type==='walk'&&!task.done){let a=task.walk,dist=Math.hypot(a.tx-a.x,a.ty-a.y);if(dist>1.5){let step=Math.min(dist,18);a.x+=(a.tx-a.x)/dist*step;a.y+=(a.ty-a.y)/dist*step}if(Math.hypot(task.target.x-a.x,task.target.y-a.y)<33)complete('Aren chegou ao lugar de encontro: agora comeza a decisión.')}}
function walkTo(x,y){if(task.type!=='walk'||task.done)return;task.walk.tx=Math.max(25,Math.min(795,x));task.walk.ty=Math.max(45,Math.min(353,y))}
function canvasClick(ev){let rect=canvas.getBoundingClientRect(),x=(ev.clientX-rect.left)/rect.width*820,y=(ev.clientY-rect.top)/rect.height*400;if(task.type==='walk'){walkTo(x,y)}else if(task.type==='inspect'&&!task.done){for(const [i,pos] of [[0,[160,105]],[1,[584,128]],[2,[640,309]]])if(Math.hypot(x-pos[0],y-pos[1])<37)return evidenceFind(i)}}
