let hold=null;document.querySelectorAll('[data-move]').forEach(b=>{function start(ev){ev.preventDefault();const d=b.dataset.move;moveBy(d);clearInterval(hold);hold=setInterval(()=>moveBy(d),135)}function stop(){clearInterval(hold);hold=null}b.addEventListener('pointerdown',start);for(const k of ['pointerup','pointercancel','pointerleave'])b.addEventListener(k,stop)});
document.addEventListener('keydown',ev=>{if($('game').classList.contains('hidden')||!$('modalWrap').classList.contains('hidden'))return;const tag=document.activeElement?.tagName;if(['INPUT','TEXTAREA','SELECT'].includes(tag))return;const keys={ArrowLeft:'left',ArrowRight:'right',ArrowUp:'up',ArrowDown:'down',a:'left',d:'right',w:'up',s:'down'};if(keys[ev.key]){if(task.type==='walk'&&!task.done){ev.preventDefault();moveBy(keys[ev.key])}}});
