const glossary=[['O Lor e o territorio','O Lor segue un curso real desde as súas cabeceiras na zona de Brañas e Fonlor, pasando pola contorna de Seoane e Folgoso, ata desembocar no Sil en Augasmestas. A división política Alto/Baixo desta obra é imaxinada e non equivale a unha fronteira hidrográfica oficial.'],['Aren e a linguaxe','Aren ten once anos ao comezo, naceu no Alto e identifícase como persoa non binaria. Empréganse principalmente fórmulas neutras e, cando cómpre, o pronome eli. Son usos propostos, non unha norma plenamente estandarizada do galego.'],['Rocking Courel, no Alto','A organización ficticia do Alto é anarcosindicalista: agrupa oficios, cooperativas, portavocías revogables e fondos colectivos de coidados. A súa base principal é o Hydra. Non representa as actividades reais do proxecto homónimo.'],['Raving Courel, no Baixo','A organización ficticia do Baixo é anarcocapitalista: fomenta a iniciativa privada, contratos e mercado entre iguais, sen privatizar o monte nin o mínimo vital de auga. A súa base é O Cráter, alcume inventado para a antiga discoteca de Folgoso. Non describe o proxecto real.'],['O monte común','O monte e os bens vitais non se poden dividir nin vender. A comunidade regula usos, coidados e restauración. As explotacións autorizadas son temporais e auditables: madeira, castañas, enerxía renovable e servizos ambientais.'],['A Mesa do Lor','Órgano ficticio de coordinación entre comunidades sobre asuntos compartidos: auga, emergencias, datos forestais, pontes, coidados e mobilidade. Non ten mando permanente nin pode anular a autonomía de cada parte.'],['Tecnoloxía e liberdade','Os sensores, os paneis solares, as microredes, os rexistros verificables e os equipos musicais reducen dependencia externa; tamén poden concentrar poder se os datos e as claves quedan nunhas poucas mans.'],['Distopía e mensaxe','O antigo sistema ORDE representa unha forma imaxinaria de control social; a súa existencia, a toma do concello e as políticas retratadas son ficción. As seis rutas finais mostran comunidades irmandadas con mellor nivel de vida, aínda que as decisións violentas poidan deixar danos.']];
function openModal(kind){modalType=kind;$('modalWrap').classList.remove('hidden');const e=$('modalContent');e.replaceChildren();const title={journey:'Os camiños de Aren',glossary:'O Courel das dúas frecuencias',menu:'A túa partida',about:'Sobre esta ficción'};setText('modalTitle',title[kind]||'Raving Courel');if(kind==='journey')showJourney(e);if(kind==='glossary')showGlossary(e);if(kind==='menu')showMenu(e);if(kind==='about')showAbout(e);$('modalClose').focus()}
function closeModal(){$('modalWrap').classList.add('hidden')}
function showJourney(e){let intro=document.createElement('p');intro.textContent=`Exploraches ${state.visited.length} das 65 escenas e descubríches ${state.endings.length} dos 6 finais. Podes volver a escenas xa descubertas para probar outra decisión.`;e.append(intro);const section=document.createElement('div');section.className='journey-grid';Object.values(STORY).forEach(s=>{if(!state.visited.includes(s.id))return;let b=makeBtn(`${String(s.id).padStart(2,'0')} · ${s.title}`,()=>{closeModal();toScene(s.id)},'journey-btn');b.innerHTML=`<span class="jnum">${String(s.id).padStart(2,'0')} · ${esc(s.year.split(' · ')[0])}</span>${esc(s.title)}`;if(s.id===state.scene)b.classList.add('current');section.append(b)});e.append(section);let h=document.createElement('h3');h.className='mini-head';h.textContent='Finais descubertos';e.append(h);let p=document.createElement('p');p.textContent=state.endings.length?state.endings.map(i=>STORY[i].title).join(' · '):'Aínda non chegaches a ningún desenlace. Todas as rutas completas conservan a irmandade.';e.append(p);let ch=document.createElement('h3');ch.className='mini-head';ch.textContent='Últimas decisións';e.append(ch);state.choices.slice(-12).reverse().forEach(c=>{let p=document.createElement('p');p.className='sidehint';p.textContent=`${c.from} → ${c.to}: ${c.label}`;e.append(p)})}
function showGlossary(e){let intro=document.createElement('p');intro.textContent='A historia mestura lugares reais con institucións, economías, comunidades e feitos inventados. Preme en cada título para coñecer o funcionamento deste Courel posible.';e.append(intro);for(const [t,d]of glossary){let det=document.createElement('details');let sum=document.createElement('summary');sum.textContent=t;let p=document.createElement('p');p.textContent=d;det.append(sum,p);e.append(det)}}
function downloadSave(){const blob=new Blob([JSON.stringify({game:'RAVING_COUREL',version:1,save:state},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='raving-courel-partida.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500)}
function showMenu(e){let p=document.createElement('p');p.textContent='A partida gárdase automaticamente neste navegador. Non se envía información a ningunha conta nin servidor. Tamén podes exportala ou importala.';e.append(p);const grid=document.createElement('div');grid.className='save-grid';group(grid,makeBtn('📥 Exportar partida',downloadSave,'smallbtn'),makeBtn('📤 Importar partida',()=>file.click(),'smallbtn'),makeBtn(state.sound?'♫ Desactivar audio':'♫ Activar audio',()=>{state.sound=!state.sound;save();updateSound();updateAmbience();showMenuRefresh();if(state.sound){soundOn();tone(442,.16)}},'smallbtn'),makeBtn('⟳ Nova ruta (conservar finais)',()=>{if(confirm('Queres reiniciar a historia? Gardaranse os finais descubertos, pero as decisións e os indicadores comezarán de novo.')){const ends=[...state.endings];state=fresh();state.endings=ends;state.started=true;save();updateAmbience();closeModal();toScene(1,false)}},'smallbtn'),makeBtn('✕ Borrar todos os datos',()=>{if(confirm('Isto borra partidas, decisións, finais e progresos deste dispositivo. Confirmas?')){state=fresh();save();updateAmbience();location.reload()}},'smallbtn'));
e.append(grid);let file=document.createElement('input');file.type='file';file.accept='application/json,.json';file.className='sr-only';file.addEventListener('change',async()=>{try{let d=JSON.parse(await file.files[0].text());if(d.game!=='RAVING_COUREL'||!d.save||!STORY[d.save.scene])throw Error('Ficheiro non válido');state={...fresh(),...d.save,started:true};save();closeModal();renderScene();toast('Partida importada correctamente.')}catch(err){feedback('');alert('Non se puido importar: '+err.message)}});e.append(file);let info=document.createElement('div');info.className='hint';info.style.marginTop='18px';info.textContent='Accesibilidade: todos os retos teñen controis táctiles e alternativa de texto. Omitir un reto non bloquea a historia, pero dá menos experiencia. O son é opcional. As animacións redúcense se está activada a preferencia de movemento reducido.';e.append(info);e.append(makeBtn('Sobre o libro, a ficción e os créditos',()=>openModal('about'),'side-link'))}
function showMenuRefresh(){if(modalType==='menu')openModal('menu')}
function showAbout(e){const p=document.createElement('p');p.innerHTML='<strong>Raving Courel: O ritmo do Lor</strong> é unha novela-videoxogo de ficción con 65 escenas, seis desenlaces e rutas que obrigan a reconsiderar determinadas decisións. A narración e a adaptación do xogo están atribuídas a <strong>ChatGPT (OpenAI)</strong>, a partir dunha idea e baixo a dirección creativa da persoa promotora. Esta edición toma como base a novela-xogo homónima de 2026.';e.append(p);for(const line of ['Rocking Courel e Raving Courel son proxectos que existen na realidade, mais as versións que aparecen aquí, as súas finalidades ficticias, as relacións entre eles e o seu suposto papel político son inventados.','O Hydra e a antiga discoteca de Folgoso empréganse como ambientación. «O Cráter» é un alcume literario inventado, non unha identificación histórica do local.','Todas as organizacións, sucesos políticos, personaxes, actos de violencia, algoritmos de control, conflitos e diálogos son ficticios. Calquera coincidencia con feitos, situacións ou persoas reais é puramente casual, agás os nomes de proxectos, lugares e referencias xeográficas expresamente empregados.','A historia procura estimular o pensamento crítico, non presentar ningún sistema económico como unha solución perfecta. A colaboración entre comunidades e a mellora dos coidados, dos servizos e da vida comunitaria mantéñense en todos os finais completos.','Código HTML, CSS e JavaScript autocontido, sen analítica, anuncios nin recursos remotos. Os sons son sintetizados no dispositivo e non reproducen composicións comerciais. Non se solicitan datos persoais.']){let q=document.createElement('p');q.textContent=line;e.append(q)}}
function nativeFullscreenActive(){return !!(document.fullscreenElement||document.webkitFullscreenElement)}
function updateFullscreenButtons(){
 const active=nativeFullscreenActive()||document.body.classList.contains('immersive-fallback');
 const action=active?'Saír da pantalla completa':'Pantalla completa';
 const gameBtn=$('fullscreenBtn'),splashBtn=$('splashFullscreenBtn');
 gameBtn.textContent=active?'⤢':'⛶';gameBtn.title=action;
 gameBtn.setAttribute('aria-label',action);gameBtn.setAttribute('aria-pressed',String(active));
 splashBtn.textContent=active?'⤢ Saír do modo ampliado':'⛶ Pantalla completa';
 splashBtn.setAttribute('aria-label',action);
}
async function toggleFullscreen(){
 if(nativeFullscreenActive()){
  try {if(document.exitFullscreen)await document.exitFullscreen();else if(document.webkitExitFullscreen)await document.webkitExitFullscreen()}
  catch(e){toast('Non se puido saír automaticamente. Usa o control do navegador.');}
 }else if(document.body.classList.contains('immersive-fallback')){
  document.body.classList.remove('immersive-fallback');
 }else{
  try{
   const root=document.documentElement;
   if(root.requestFullscreen)await root.requestFullscreen();
   else if(root.webkitRequestFullscreen)await root.webkitRequestFullscreen();
   else throw new Error('Pantalla completa non dispoñible');
  }catch(e){
   document.body.classList.add('immersive-fallback');
   toast('Este navegador non permite pantalla completa desde a web. Activouse a vista ampliada.');
  }
 }
 updateFullscreenButtons();
}
