function init(){updateSplash();updateSound();updateFullscreenButtons();$('splashFullscreenBtn').addEventListener('click',toggleFullscreen);$('fullscreenBtn').addEventListener('click',toggleFullscreen);document.addEventListener('fullscreenchange',updateFullscreenButtons);document.addEventListener('webkitfullscreenchange',updateFullscreenButtons);$('startBtn').addEventListener('click',()=>handleStart(true));$('continueBtn').addEventListener('click',()=>handleStart(false));$('splashAbout').addEventListener('click',()=>openModal('about'));
$('backBtn').onclick=back;$('mobileBack').onclick=back;$('menuBtn').onclick=()=>openModal('menu');$('soundBtn').onclick=()=>{state.sound=!state.sound;save();updateSound();updateAmbience();if(state.sound){soundOn();tone(440,.14);toast('♫ Audio sintético activado')}else toast('Audio desactivado')};$('storyToggle').onclick=()=>{const n=$('narrative'),yes=n.classList.toggle('expanded');$('storyToggle').textContent=yes?'Pechar o relato ↑':`Ler a escena completa · ${STORY[state.scene].body.length} parágrafos ↓`;$('storyToggle').setAttribute('aria-expanded',String(yes))};$('hintBtn').onclick=()=>{feedback('PISTA · '+hints[task.type]);};$('assistBtn').onclick=()=>{if(confirm('Queres continuar sen resolver este reto? A aventura segue, pero a experiencia recibida será menor.')){state.assisted++;task.assisted=true;complete('Actividade omitida para facilitar a lectura e accesibilidade.')}};document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openModal(b.dataset.open));$('modalClose').onclick=closeModal;$('modalWrap').addEventListener('pointerdown',ev=>{if(ev.target===$('modalWrap'))closeModal()});document.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&!$('modalWrap').classList.contains('hidden'))closeModal()});}
init();
